entries[53736] = { ["name"] = "Seal of Corruption", ["text"] = "14% of base mana\nInstant\nFills the Paladin with holy power, causing attacks to apply Blood Corruption, which deals [(0.013 * Spell power + 0.025 * Attack power) * 5] additional Holy damage over 15 sec. Each of the Paladin's attacks also deals up to 33% weapon damage as additional Holy damage, based on the number of stacks. Blood Corruption can stack up to 5 times. Only one Seal can be active on the Paladin at any one time. Lasts 30 min.\n\nUnleashing this Seal's energy will deal (1 + 0.22 * Spell power + 0.14 * Attack power) Holy damage to an enemy, increased by 10% for each application of Blood Corruption on the target." }
entries[53739] = { ["name"] = "Seal of Corruption", ["text"] = "100 yd range\nInstant\nFills the Paladin with holy power, causing attacks to apply Blood Corruption, which deals [(0.013 * Spell power + 0.025 * Attack power) * 6] additional Holy damage over 15 sec. Blood Corruption can stack up to 5 times. Each of the Paladin's attacks also deals up to 33% weapon damage as additional Holy damage, based on the number of stacks. Only one Seal can be active on the Paladin at any one time. Lasts until cancelled.\n\nUnleashing this Seal's energy will deal (1 + 0.22 * Spell power + 0.14 * Attack power) Holy damage to an enemy, increased by 10% for each application of Blood Corruption on the target." }
