entries[53895] = { ["name"] = "Crazy Alchemist's Potion", ["text"] = "3 sec cast\nReagents:\nGoldclover (2), Imbued Vial\n70\nRequires Alchemy\n(400)\nUse: Restores 3100 to 3500 health and 4200 to 4400 mana. Sometimes has the effect of an additional random potion. (1 Min Cooldown)" }
